suppressPackageStartupMessages({library(dplyr);library(tidyr)});set.seed(20260828)
a<-grep('^--file=',commandArgs(FALSE),value=TRUE);p<-normalizePath(gsub('~\\+~',' ',if(length(a))sub('^--file=','',a[1])else'.'));od<-if(file.info(p)$isdir)p else dirname(p);st<-tools::file_path_sans_ext(basename(p))
u<-function(x)read.csv(text=rawToChar(memDecompress(base64enc::base64decode(x),type='gzip')),stringsAsFactors=FALSE,check.names=FALSE,na.strings=c('NA',''))
xe<-function(x){x[is.na(x)]<-'';x<-gsub('&','&amp;',x,fixed=T);x<-gsub('<','&lt;',x,fixed=T);gsub('>','&gt;',x,fixed=T)};xc<-function(n){z<-character(length(n));for(j in seq_along(n)){k<-n[j];s<-'';while(k>0){k<-k-1;s<-paste0(intToUtf8(65+k%%26),s);k<-k%/%26};z[j]<-s};z}
wx<-function(ds,path){td<-tempfile('x');dir.create(td);for(z in c('_rels','xl','xl/_rels','xl/worksheets'))dir.create(file.path(td,z),recursive=T,showWarnings=F);writeLines(paste0('<?xml version="1.0"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/>',paste0('<Override PartName="/xl/worksheets/sheet',seq_along(ds),'.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>',collapse=''),'</Types>'),file.path(td,'[Content_Types].xml'));writeLines('<?xml version="1.0"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>',file.path(td,'_rels/.rels'));writeLines(paste0('<?xml version="1.0"?><workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets>',paste0('<sheet name="',names(ds),'" sheetId="',seq_along(ds),'" r:id="rId',seq_along(ds),'"/>',collapse=''),'</sheets></workbook>'),file.path(td,'xl/workbook.xml'));writeLines(paste0('<?xml version="1.0"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">',paste0('<Relationship Id="rId',seq_along(ds),'" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet',seq_along(ds),'.xml"/>',collapse=''),'</Relationships>'),file.path(td,'xl/_rels/workbook.xml.rels'));for(k in seq_along(ds)){d<-ds[[k]];names(d)<-toupper(names(d));m<-rbind(names(d),as.matrix(d));rr<-vapply(seq_len(nrow(m)),function(i)paste0('<row r="',i,'">',paste0(vapply(seq_len(ncol(m)),function(j)sprintf('<c r="%s%d" t="inlineStr"><is><t>%s</t></is></c>',xc(j),i,xe(m[i,j])),''),collapse=''),'</row>'),'' );writeLines(paste0('<?xml version="1.0"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetData>',paste0(rr,collapse=''),'</sheetData></worksheet>'),file.path(td,'xl/worksheets',paste0('sheet',k,'.xml')))};old<-setwd(td);on.exit(setwd(old),add=T);if(file.exists(path))unlink(path);utils::zip(path,list.files('.',recursive=T,all.files=T,no..=T),flags='-q')}
e<-function(x){x<-gsub('\\\\','\\\\\\\\',as.character(x));gsub('([{}])','\\\\\\1',x)};wr<-function(z,title,path){con<-file(path,'wb');on.exit(close(con));w<-function(...)writeLines(paste0(...),con,useBytes=T);w('{\\rtf1\\ansi\\deff0{\\fonttbl{\\f0 Arial;}}\\landscape\\paperw15840\\paperh12240\\margl600\\margr600\\margt500\\margb600');w('\\pard\\f0\\fs15 PILOT\\tab Confidential\\tab Page {\\field{\\*\\fldinst PAGE}} of {\\field{\\*\\fldinst NUMPAGES}}\\par\\pard\\qc\\b\\fs19 ',e(title),'\\b0\\par\\pard\\qc\\fs15 Safety Population\\par\\par');n<-ncol(z);ends<-cumsum(c(5500,rep(9140/(n-1),n-1)));for(i in 0:nrow(z)){v<-if(i==0)names(z)else as.character(z[i,]);b<-if(i==0)'\\clbrdrt\\brdrs\\brdrw15\\clbrdrb\\brdrs\\brdrw15'else if(i==nrow(z))'\\clbrdrb\\brdrs\\brdrw15'else'';w('\\trowd\\trgaph60',if(i==0)'\\trhdr'else'',paste0(b,'\\cellx',ends,collapse=''));for(j in seq_len(n))w('\\intbl',if(j==1)'\\ql'else'\\qc',if(i==0)'\\b'else'\\b0','\\fs13 ',e(v[j]),'\\cell');w('\\row')};w('\\pard\\ql\\fs12\\par Values are number and percentage of subjects with at least one treatment-emergent adverse event.\\par Source: simulated data generated by this standalone program.\\par}')}
sim<-function(a,e){outa<-list();oute<-list();i<-1L;for(t in sort(unique(a$TRT01AN))){ids<-a$USUBJID[a$TRT01AN==t];for(id0 in sample(ids,2*length(ids),T)){id<-sprintf('PILOT-%04d',i);i<-i+1L;outa[[length(outa)+1]]<-data.frame(USUBJID=id,TRT01AN=t,SAFFL='Y');x<-e[e$USUBJID==id0,,drop=F];if(nrow(x)){x$USUBJID<-id;oute[[length(oute)+1]]<-x}}};list(ADSL=bind_rows(outa),ADAE=bind_rows(oute))}

A<-"H4sIAB20kWoC/2WSSwrCQBBE955lhO6unnyWEQlEgoqZLLz/RXThwlRBVo+azqOofdsvt+Va2quZT/eyTfO8np7L+mhnM/9+xcr7HwQDlMGPJEvNI6mS6fhMz2CQNyPfdRPiQkIIhCT93CuDjm28FyLGPtKZMI6ECxHhEOFg4agS4YZDhEOEY2QCqRhiDDGGGENGAe4Y0jF4FBBjcMVpDHjCKboJjoht/ib8ARxCiAQxAwAA"
E<-""
N0<-45L
adsl<-u(A);adae<-u(E);x<-sim(adsl,adae);den<-x$ADSL%>%count(TRT01AN,name='D');labs<-setNames(paste0(c('Placebo','Treatment 54 mg','Treatment 81 mg')[match(den$TRT01AN,c(0,54,81))],' (N=',den$D,')'),den$TRT01AN);labs<-c(labs,Total=paste0('Total (N=',sum(den$D),')'));ae<-x$ADAE;if('TRTEMFL'%in%names(ae))ae<-ae%>%filter(TRTEMFL=='Y');if(!'AEBODSYS'%in%names(ae))ae$AEBODSYS<-'Adverse Events';if(!'AEDECOD'%in%names(ae))ae$AEDECOD<-'Adverse Event';q<-bind_rows(ae%>%mutate(T=as.character(TRTAN)),ae%>%mutate(T='Total'))%>%group_by(AEBODSYS,AEDECOD,T)%>%summarise(N=n_distinct(USUBJID),.groups='drop')%>%left_join(bind_rows(den%>%transmute(T=as.character(TRT01AN),D),data.frame(T='Total',D=sum(den$D))),by='T')%>%mutate(V=ifelse(N==0,'0',sprintf('%d (%.1f%%)',N,100*N/D)))%>%select(AEBODSYS,AEDECOD,T,V)%>%pivot_wider(names_from=T,values_from=V,values_fill='0');names(q)[names(q)=='0']<-labs['0'];names(q)[names(q)=='54']<-labs['54'];names(q)[names(q)=='81']<-labs['81'];names(q)[names(q)=='Total']<-labs['Total']

# Display each System Organ Class only on the first row of its group.
out <- q %>%
  arrange(AEBODSYS, AEDECOD) %>%
  mutate(
    SYSTEM_ORGAN_CLASS_DISPLAY = if_else(
      row_number() == 1L | AEBODSYS != lag(AEBODSYS),
      AEBODSYS,
      ''
    )
  ) %>%
  select(
    System.Organ.Class = SYSTEM_ORGAN_CLASS_DISPLAY,
    Preferred.Term = AEDECOD,
    all_of(unname(labs))
  )

wx(x,file.path(od,paste0(st,'_simulated_data.xlsx')));wr(out,paste0('Table ',4,'. Treatment-Emergent Adverse Events by System Organ Class and Preferred Term'),file.path(od,paste0(st,'.rtf')));message(sprintf('Created %s: original N=%d; simulated N=%d',st,N0,n_distinct(x$ADSL$USUBJID)))
